script:
function setupList() {
    return {
        actions: [{
            label: __('Recruitment workspace'),
            onClick: () => window.location.assign('/cskh'),
        }],
    }
}

class CRMLead {
    onLoad() {
        this.actions = [{
            label: __('Open in Recruitment workspace'),
            onClick: () => window.location.assign('/cskh/work-item?lead=' + encodeURIComponent((this.doc && this.doc.name) || '')),
        }]
    }
}
